/**
 * Carlito Font (SIL Open Font License) - Metric-compatible with Calibri.
 * SubsetParameter: Latin printable, digits, currency symbols, punctuation.
 * Lazy-loaded during PDF generation only (~68 KB total).
 */
export const CARLITO_REGULAR_BASE64 = '';
export const CARLITO_BOLD_BASE64 = '';

/**
 * Registers Carlito Regular and Bold into a jsPDF document instance.
 * @param {import('jspdf').jsPDF} doc
 */
export function registerCarlitoFont(doc) {
  if (!doc) return;
  try {
    doc.addFileToVFS('Carlito-Regular.ttf', CARLITO_REGULAR_BASE64);
    doc.addFont('Carlito-Regular.ttf', 'Carlito', 'normal');
    doc.addFileToVFS('Carlito-Bold.ttf', CARLITO_BOLD_BASE64);
    doc.addFont('Carlito-Bold.ttf', 'Carlito', 'bold');
    doc.setFont('Carlito', 'normal');
  } catch (err) {
    console.warn('Could not register Carlito font in jsPDF, falling back to standard font:', err);
  }
}
